23505,23506)

ORDER BY 1

OPEN PRODUTO

FETCH NEXT FROM PRODUTO INTO @COD_PROD
WHILE @@FETCH_STATUS = 0
	BEGIN
		DECLARE NF_ENT CURSOR FOR
					SELECT 
						top 1 
						CB.Numero,
						CB.Chv_Acesso,
						FB.Fantasia,
						Estado_Com,
						CB.Dat_Emissao,
						Prc_Unitario,
						Qtd_PedFat
					FROM NFEIT IT, NFECB CB, PRODU PR,  FABRI FB, FBXES ES, FORNE FN
					WHERE 
					IT.Cod_Estabe = 1	
				AND IT.Cod_Produto = @COD_PROD
				AND CB.Dat_Emissao <= '20240630'
				AND	IT.Cod_Estabe = CB.Cod_Estabe
				AND	IT.PROTOCOLO = CB.Protocolo
				AND IT.Cod_Produto = PR.Codigo
				AND PR.Cod_Fabricante = FB.Codigo
				AND FB.Codigo = ES.Cod_Fabric
				AND ES.Cod_Estabe = IT.Cod_Estabe
				AND ((CB.Cod_EmiFornec = FN.Codigo AND CB.Cgc_Cpf = FN.Cgc_Cpf) OR (CB.Cod_EmiFornec = FB.Codigo AND CB.Cgc_Cpf = FB.Cgc_Cpf) )
		
				order by 5 desc

			OPEN NF_ENT

			FETCH NEXT FROM NF_ENT INTO @NUM_NOTA, @CHV_ACESSO, @FANTASIA, @ESTADO, @DTEMISSAO, @VLR, @QTD

			WHILE @@FETCH_STATUS = 0
				BEGIN
					
					PRINT CAST(@COD_PROD AS NVARCHAR(255)) +';'
					+ CAST(@NUM_NOTA AS NVARCHAR(255)) +';'''
					+ CAST(@CHV_ACESSO AS NVARCHAR(255)) +';'
					+ CAST(@FANTASIA AS NVARCHAR(255)) +';'
					+ CAST(@ESTADO AS NVARCHAR(255)) +';'
					+ CAST(@DTEMISSAO AS NVARCHAR(255)) +';'
					+ CAST(@VLR AS NVARCHAR(255)) +';'
					+ CAST(@QTD AS NVARCHAR(255))

				FETCH NEXT FROM NF_ENT INTO @NUM_NOTA, @CHV_ACESSO, @FANTASIA, @ESTADO, @DTEMISSAO, @VLR, @QTD

				END;
				CLOSE NF_ENT
				DEALLOCATE NF_ENT

		FETCH NEXT FROM PRODUTO INTO @COD_PROD
		END
		CLOSE PRODUTO
		DEALLOCATE PRODUTO